/// <summary>
/// Controller for the multithreaded batch monitoring test job.
/// </summary>
class METBatchMonitoringMultiTestController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Wires the controller to the service class and method.
/// </summary>
protected void new()
{
    super(classStr(METBatchMonitoringMultiTestService), methodStr(METBatchMonitoringMultiTestService, process), SysOperationExecutionMode::Synchronous);
}

public static METBatchMonitoringMultiTestController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METBatchMonitoringMultiTestController controller = new METBatchMonitoringMultiTestController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

public static void main(Args _args)
{
    METBatchMonitoringMultiTestController controller = METBatchMonitoringMultiTestController::construct(_args);
    controller.batchInfo().parmBatchExecute(true);
    controller.startOperation();
}
